// BIOS images in public/roms: the standard miniVIC BIOS first, then the KEYB/SD fork (extended keyboard,
// SDSC v1/v2 and SDHC cards, sector read/write for programs) and the Arcade BIOS of the Arcade6502 cabinet
// (game front-end driven by the joysticks, no keyboard).
// List generated by scripts/sync-bios.mjs: do not edit it by hand.

export type BiosId = 'std' | 'keybsd' | 'arcade';

export interface RomInfo {
  id: BiosId;
  file: string;
  title: string;
  version: string;
}

export const ROMS: RomInfo[] = [
  { id: 'std', file: 'minivic.bin', title: 'BIOS 24.10.26 (standard)', version: '24.10.26' },
  { id: 'keybsd', file: 'minivic_keybsd.bin', title: 'BIOS 03.11.26 KEYB/SD', version: '03.11.26 KEYB/SD' },
  { id: 'arcade', file: 'arcade.bin', title: 'Arcade BIOS 12.11.26 ARCADE', version: '12.11.26 ARCADE' },
];
